            NSSound.beep()
            return
        }
        if let refusal = plan.refusal {
            host.transcriptRefuse(refusal.sentence)
            return
        }
        let held = rangeSet
        rangeSet = nil
        if !host.transcriptDelete(plan.range, name: "Delete Pause") { rangeSet = held }
