import json
import re

ROOT = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/docs/site/src/content/docs/"
INV = "/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/"

TOP = {"transcript-tab"}


def slug(heading):
    text = heading.strip().replace("`", "").lower()
    text = re.sub(r"[^\w\s-]", "", text)
    return re.sub(r"\s", "-", text)


brief = json.load(open(INV + "chunks/captions-4.json"))
out = {}
problems = []
for page in brief["pages"]:
    text = open(ROOT + page["slug"] + ".mdx").read()
    have = {slug(m) for m in re.findall(r"^#{2,4} (.+)$", text, re.M)}
    for feature in page["features"]:
        fid = feature["id"]
        if fid in TOP:
            out[fid] = ""
        elif feature["anchor"] in have:
            out[fid] = feature["anchor"]
        else:
            problems.append((fid, feature["anchor"]))

json.dump(out, open(INV + "anchors/captions-4.json", "w"), indent=1, ensure_ascii=False)
print(len(out), "anchors written; missing:", problems)

